const services = {
  id:'services',
  copy:{
    title: 'Services',
    list: [1, 2, 3, 4, 5]
  }
};

const listItems = services.copy.list.map((list) => <li key={list}>{list}</li>);


const Services = () => (
  <>
  <section className='container-fluid px-0 min-vh-100 parallax' id={services.id}></section>
  <ul>{listItems}</ul>  
  <section />
  </>
)

export default Services;
